const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));let selected=null;async function get(u){const r=await fetch(u,{cache:'no-store'});if(!r.ok)throw Error();return r.json()}function table(e,r){return `<article class="race-table"><header><div><span>${esc(e.stage||'Results')}</span><h3>${esc(e.name)}</h3></div><b>${r.length} riders</b></header><div class="table-scroll"><table><thead><tr><th>Pos</th><th>Rider</th><th>Time</th></tr></thead><tbody>${r.map((x,i)=>`<tr class="${i<3?'podium':''}"><td class="place">${x.position}</td><td><button class="rider rider-detail" data-laps="${esc(JSON.stringify(x.laps||[]))}"><span class="bib">${esc(x.bib)}</span><span class="name">${esc(x.name)}</span></button></td><td class="time">${esc(x.time)}</td></tr>`).join('')}</tbody></table></div></article>`}function wireDetails(){document.querySelectorAll('.rider-detail').forEach(b=>b.onclick=()=>{const laps=JSON.parse(b.dataset.laps),current=b.closest('tr').nextElementSibling;if(current&&current.classList.contains('lap-detail'))return current.remove();const row=document.createElement('tr');row.className='lap-detail';row.innerHTML=`<td></td><td colspan="2">${laps.length?laps.map(x=>'Lap '+x.lap_number+': <b>'+esc(x.time)+'</b>').join(' · '):'No individual lap times recorded'}</td>`;b.closest('tr').after(row)})}async function render(){try{const f=await get('/api/public/events');$('#status-badge').textContent=f.status;const groups=[...new Set(f.events.map(e=>e.tournament||'Tournament'))];if(!selected||!groups.includes(selected))selected=groups[0];$('#event-tabs').innerHTML=groups.map(x=>`<button class="tab ${x===selected?'active':''}" data-id="${esc(x)}">${esc(x)}</button>`).join('');$('#event-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.id;render()});const events=f.events.filter(e=>(e.tournament||'Tournament')===selected);if(!events.length){$('#race-title').textContent='No published results';return}const data=await Promise.all(events.map(e=>get('/api/public/events/'+encodeURIComponent(e.id)+'/results')));$('#race-title').textContent=selected;$('#result-count').textContent=`${events.length} ${events.length===1?'event':'events'} · ${data.reduce((n,r)=>n+r.length,0)} riders`;$('#round-nav').innerHTML='';$('#stage-results').innerHTML=`<div class="race-grid ${events.length===1?'single':''}">${events.map((e,i)=>table(e,data[i])).join('')}</div>`;wireDetails()}catch{$('#race-title').textContent='Waiting for timing feed';$('#result-count').textContent='The live results service is not connected yet.'}}render();setInterval(render,15000);

